func appendUnique1(slice []int, val int) []int {
    for _, v := range slice {
        if v == val {
            return slice
        }
    }
    return append(slice, val)
}

func appendUnique2(arr []int, num int) []int {
    for _, n := range arr {
        if n == num {
            return arr
        }
    }
    return append(arr, num)
}

